CREATE TABLE public.stage4_concurrency_ids (name text PRIMARY KEY,id uuid NOT NULL);
REVOKE ALL ON public.stage4_concurrency_ids FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT ON public.stage4_concurrency_ids TO authenticated;

SELECT set_config('request.jwt.claim.sub','73000000-0000-4000-8000-000000000001',false);
SET ROLE authenticated;
SET search_path=public,extensions;

